CREATE TABLE IF NOT EXISTS learning_definitions (id TEXT NOT NULL, version TEXT NOT NULL, state TEXT NOT NULL, document TEXT NOT NULL, digest TEXT NOT NULL, created_at BIGINT NOT NULL, PRIMARY KEY(id,version));
CREATE TABLE IF NOT EXISTS learning_attempts (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, definition_id TEXT NOT NULL, definition_version TEXT NOT NULL, request_key TEXT NOT NULL, state TEXT NOT NULL, snapshot TEXT, snapshot_hash TEXT, submitted_at BIGINT, created_at BIGINT NOT NULL, UNIQUE(user_id,definition_id,definition_version,request_key), FOREIGN KEY(definition_id,definition_version) REFERENCES learning_definitions(id,version));
CREATE TABLE IF NOT EXISTS learning_assignments (attempt_id TEXT PRIMARY KEY REFERENCES learning_attempts(id) ON DELETE CASCADE, reviewer_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS learning_events (id TEXT PRIMARY KEY, attempt_id TEXT NOT NULL REFERENCES learning_attempts(id) ON DELETE CASCADE, event_key TEXT NOT NULL, actor_id TEXT, kind TEXT NOT NULL, document TEXT NOT NULL, created_at BIGINT NOT NULL, UNIQUE(attempt_id,event_key));
CREATE TABLE IF NOT EXISTS learning_evidence (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, activity_id TEXT NOT NULL, curriculum_version TEXT NOT NULL, definition_version TEXT NOT NULL, attempt_id TEXT NOT NULL REFERENCES learning_attempts(id) ON DELETE CASCADE, document TEXT NOT NULL, created_at BIGINT NOT NULL, UNIQUE(attempt_id));
CREATE TABLE IF NOT EXISTS learning_xp (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, activity_id TEXT NOT NULL, curriculum_version TEXT NOT NULL, amount INTEGER NOT NULL, attempt_id TEXT NOT NULL REFERENCES learning_attempts(id) ON DELETE CASCADE, PRIMARY KEY(user_id,activity_id,curriculum_version));
CREATE TABLE IF NOT EXISTS learning_audit (id TEXT PRIMARY KEY, actor_id TEXT REFERENCES users(id) ON DELETE SET NULL, action TEXT NOT NULL, resource_id TEXT NOT NULL, document TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS learning_certificates (id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id) ON DELETE SET NULL, definition_id TEXT NOT NULL, curriculum_version TEXT NOT NULL, status TEXT NOT NULL, public_consent INTEGER NOT NULL, document TEXT NOT NULL, issued_at BIGINT NOT NULL, revoked_at BIGINT, UNIQUE(user_id,definition_id,curriculum_version));
CREATE INDEX IF NOT EXISTS learning_attempt_owner ON learning_attempts(user_id,created_at);
CREATE INDEX IF NOT EXISTS learning_evidence_owner ON learning_evidence(user_id,curriculum_version);
INSERT INTO schema_migrations (version) VALUES (4) ON CONFLICT(version) DO NOTHING;
CREATE TABLE IF NOT EXISTS learning_consents (user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, definition_id TEXT NOT NULL, curriculum_version TEXT NOT NULL, created_at BIGINT NOT NULL, PRIMARY KEY(user_id,definition_id,curriculum_version));
